'use strict'

/**
 * Get unique error field name
 */
const getUniqueErrorMessage = (err) => {
    let output
    try {
        let fieldName = err.message.substring(err.message.lastIndexOf('.$') + 2, err.message.lastIndexOf('_1'))
        output = fieldName.charAt(0).toUpperCase() + fieldName.slice(1) + ' already exists'
    } catch (ex) {
        output = 'Unique field already exists'
    }

    return output
}

/**
 * Get the error message from error object
 */
const getErrorMessage = (err) => {
    let message = ''

    if (err.code) {
        switch (err.code) {
            case 11000:
            case 11001:
                message = getUniqueErrorMessage(err)
                break
            default:
                message = 'Something went wrong'
        }
    } else {
        for (let errName in err.errors) {
            if (err.errors[errName].message) message = err.errors[errName].message
        }
    }

    return message
}

export default {getErrorMessage}

import mongoose from 'mongoose'
import dbErrorHandler from './dbErrorHandler'

// An expected failure with a status the client should see, e.g. new HttpError(404, 'Shop not found').
export class HttpError extends Error {
  constructor (status, message) {
    super(message)
    this.status = status
  }
}

// Wraps an async handler/middleware/param callback so a rejected promise goes to errorMiddleware
// instead of being repeated as try/catch in every handler (D-02).
// `fallback` replaces any unexpected (non-HttpError) error, for handlers that hide DB details
// behind a fixed message, e.g. asyncHandler(fn, new HttpError(400, 'Could not retrieve user')).
export const asyncHandler = (fn, fallback) => (req, res, next, ...args) =>
  Promise.resolve(fn(req, res, next, ...args))
    .catch(err => next(err instanceof HttpError || !fallback ? err : fallback))

// Single place that turns errors into responses. Every error body is { error: string } (D-07).
export const errorMiddleware = (err, req, res, next) => {
  if (res.headersSent) return next(err)
  if (err instanceof HttpError) {
    return res.status(err.status).json({ error: err.message })
  }
  if (err.name === 'UnauthorizedError') { // express-jwt
    return res.status(401).json({ error: err.name + ': ' + err.message })
  }
  if (err instanceof mongoose.Error || err.name === 'MongoError') {
    return res.status(400).json({ error: dbErrorHandler.getErrorMessage(err) })
  }
  console.log(err)
  res.status(400).json({ error: err.name + ': ' + err.message })
}

import fs from 'fs'
import defaultImage from '../../client/assets/images/default.png'

export const applyImage = (doc, files) => {
  if (files && files.image) {
    doc.image.data = fs.readFileSync(files.image.path)
    doc.image.contentType = files.image.type
  }
}

export const photoHandler = key => (req, res, next) => {
  if (req[key].image.data) {
    res.set('Content-Type', req[key].image.contentType)
    return res.send(req[key].image.data)
  }
  next()
}

export const defaultPhoto = (req, res) => res.sendFile(process.cwd() + defaultImage)

export const readWithoutImage = key => (req, res) => {
  req[key].image = undefined
  return res.json(req[key])
}

export const requireOwner = (key, ownerField) => (req, res, next) => {
  const ok = req[key] && req.auth && req[key][ownerField]._id == req.auth._id
  if (!ok) return res.status('403').json({ error: 'User is not authorized' })
  next()
}

import formidable from 'formidable'
import { HttpError } from '../helpers/errors'

export const parseMultipart = errorMessage => (req, res, next) => {
  let form = new formidable.IncomingForm()
  form.keepExtensions = true
  form.parse(req, (err, fields, files) => {
    if (err) return next(new HttpError(400, errorMessage))
    req.fields = fields
    req.files = files
    next()
  })
}

import mongoose from 'mongoose'
import crypto from 'crypto'
const UserSchema = new mongoose.Schema({
  name: {
    type: String,
    trim: true,
    required: 'Name is required'
  },
  email: {
    type: String,
    trim: true,
    unique: 'Email already exists',
    match: [/.+\@.+\..+/, 'Please fill a valid email address'],
    required: 'Email is required'
  },
  hashed_password: {
    type: String,
    required: "Password is required"
  },
  salt: String,
  updated: Date,
  created: {
    type: Date,
    default: Date.now
  },
  seller: {
    type: Boolean,
    default: false
  },
  stripe_seller: {},
  stripe_customer: {}
})

UserSchema
  .virtual('password')
  .set(function(password) {
    this._password = password
    this.salt = this.makeSalt()
    this.hashed_password = this.encryptPassword(password)
  })
  .get(function() {
    return this._password
  })

UserSchema.path('hashed_password').validate(function(v) {
  if (this._password && this._password.length < 6) {
    this.invalidate('password', 'Password must be at least 6 characters.')
  }
  if (this.isNew && !this._password) {
    this.invalidate('password', 'Password is required')
  }
}, null)

// D-08: scrypt with a random salt. Hashes are stored as "scrypt$<hex>"; older unprefixed values are
// HMAC-SHA1 from the original code, still accepted at sign-in and upgraded (see auth.controller signin).
const HASH_PREFIX = 'scrypt$'

UserSchema.methods = {
  authenticate: function(plainText) {
    const expected = Buffer.from(this.isLegacyHash() ? this.legacyEncrypt(plainText) : this.encryptPassword(plainText))
    const actual = Buffer.from(this.hashed_password || '')
    return expected.length > 0 && expected.length === actual.length && crypto.timingSafeEqual(expected, actual)
  },
  encryptPassword: function(password) {
    if (!password) return ''
    // ponytail: sync scrypt (~50ms) blocks the event loop per sign-in; the mongoose virtual setter must be sync.
    return HASH_PREFIX + crypto.scryptSync(password, this.salt, 64).toString('hex')
  },
  isLegacyHash: function() {
    return !!this.hashed_password && !this.hashed_password.startsWith(HASH_PREFIX)
  },
  legacyEncrypt: function(password) {
    if (!password) return ''
    try {
      return crypto.createHmac('sha1', this.salt).update(password).digest('hex')
    } catch (err) {
      return ''
    }
  },
  makeSalt: function() {
    return crypto.randomBytes(16).toString('hex')
  }
}

export default mongoose.model('User', UserSchema)

