// Persists auction data independently of the transport layer.
import Auction from '../models/auction.model'
import extend from 'lodash/extend'
import { applyImage } from '../helpers/image'

// The auction service layer grows in D-04.
const placeBid = (auctionId, bid) => {
  const amount = Number(bid.bid)
  if (!Number.isFinite(amount) || amount <= 0) return null
  bid.bid = amount
  const now = new Date()
  return Auction.findOneAndUpdate(
    { _id: auctionId, bidStart: { $lte: now }, bidEnd: { $gt: now },
      $or: [{ 'bids.0.bid': { $lt: amount } }, { bids: { $eq: [] }, startingBid: { $lt: amount } }] },
    { $push: { bids: { $each: [bid], $position: 0 } } },
    { new: true })
    .populate('bids.bidder', '_id name')
    .populate('seller', '_id name')
    .exec()
}

const create = async (fields, seller, files) => {
  let auction = new Auction(fields)
  auction.seller = seller
  applyImage(auction, files)
  return await auction.save()
}

const getById = id => Auction.findById(id).populate('seller', '_id name').populate('bids.bidder', '_id name').exec()

const update = async (auction, fields, files) => {
  auction = extend(auction, fields)
  auction.updated = Date.now()
  applyImage(auction, files)
  return await auction.save()
}

const remove = async auction => await auction.remove()

const listOpen = () => Auction.find({ 'bidEnd': { $gt: new Date() }}).sort('bidStart').populate('seller', '_id name').populate('bids.bidder', '_id name')

const listBySeller = userId => Auction.find({seller: userId}).populate('seller', '_id name').populate('bids.bidder', '_id name')

const listByBidder = userId => Auction.find({'bids.bidder': userId}).populate('seller', '_id name').populate('bids.bidder', '_id name')

export default { placeBid, create, getById, update, remove, listOpen, listBySeller, listByBidder }

import {Order, CartItem} from '../models/order.model'
import Shop from '../models/shop.model'

const create = async (orderData, user) => {
  orderData.user = user
  let order = new Order(orderData)
  return await order.save()
}

const listByShop = shopId => Order.find({"products.shop": shopId})
  .populate({path: 'products.product', select: '_id name price'})
  .sort('-created')
  .exec()

const updateItemStatus = (cartItemId, status, shopId) => Order.updateOne({
  products: { $elemMatch: { _id: cartItemId, shop: shopId } }
}, {
  'products.$.status': status
})

const statusValues = () => CartItem.schema.path('status').enumValues

const getById = id => Order.findById(id).populate('products.product', 'name price').populate('products.shop', 'name').exec()

const listByUser = userId => Order.find({ "user": userId })
  .sort('-created')
  .exec()

const isBuyerOrSeller = async (order, userId) => {
  if (String(order.user) === userId) return true
  const shopIds = order.products.map(item => item.shop && item.shop._id)
  return Boolean(await Shop.exists({ _id: { $in: shopIds }, owner: userId }))
}

export default { create, listByShop, updateItemStatus, statusValues, getById, listByUser, isBuyerOrSeller }

// All Stripe access lives here (D-03). No req/res: callers decide how failures become HTTP responses.
import request from 'request'
import stripe from 'stripe'
import config from './../../config/config'

const myStripe = stripe(config.stripe_test_secret_key)

// Exchange a Stripe Connect OAuth code for the seller's account details.
// Resolves with Stripe's response body, which has `error`/`error_description` when the code is rejected.
const connectSeller = (code) => new Promise((resolve, reject) => {
  request({
    url: 'https://connect.stripe.com/oauth/token',
    method: 'POST',
    json: true,
    body: { client_secret: config.stripe_test_secret_key, code, grant_type: 'authorization_code' }
  }, (error, response, body) => error ? reject(error) : resolve(body))
})

// Attach the buyer's card to their Stripe customer, creating the customer on first purchase.
// Returns the customer id.
const saveCustomer = async (user, cardToken) => {
  const customer = user.stripe_customer
    ? await myStripe.customers.update(user.stripe_customer, { source: cardToken })
    : await myStripe.customers.create({ email: user.email, source: cardToken })
  return customer.id
}

// Charge a platform customer on the seller's connected account. `amount` is in dollars.
const chargeCustomer = async (customerId, sellerAccountId, amount) => {
  const account = { stripeAccount: sellerAccountId }
  const token = await myStripe.tokens.create({ customer: customerId }, account)
  return myStripe.charges.create({ amount: amount * 100, currency: 'usd', source: token.id }, account)
}

export default { connectSeller, saveCustomer, chargeCustomer }

import Product from '../models/product.model'
import extend from 'lodash/extend'
import { applyImage } from '../helpers/image'

const create = async (fields, shop, files) => {
  let product = new Product(fields)
  product.shop = shop
  applyImage(product, files)
  return await product.save()
}

const getById = id => Product.findById(id).populate('shop', '_id name').exec()

const update = async (product, fields, files) => {
  product = extend(product, fields)
  product.updated = Date.now()
  applyImage(product, files)
  return await product.save()
}

const remove = async product => await product.remove()

const removeByShop = shopId => Product.deleteMany({ shop: shopId })

const listByShop = shopId => Product.find({shop: shopId}).populate('shop', '_id name').select('-image')

const listLatest = () => Product.find({}).sort('-created').limit(5).populate('shop', '_id name').exec()

const listRelated = product => Product.find({ "_id": { "$ne": product }, "category": product.category}).limit(5).populate('shop', '_id name').exec()

const listCategories = () => Product.distinct('category',{})

const search = ({ search, category }) => {
  const query = {}
  if(search)
    query.name = {'$regex': search, '$options': "i"}
  if(category && category != 'All')
    query.category = category
  return Product.find(query).populate('shop', '_id name').select('-image').exec()
}

const decreaseStock = orderProducts => {
  let bulkOps = orderProducts.map((item) => {
    return {
      "updateOne": {
        "filter": { "_id": item.product._id },
        "update": { "$inc": {"quantity": -item.quantity} }
      }
    }
  })
  return Product.bulkWrite(bulkOps, {})
}

const increaseStock = (productId, quantity) => Product.findByIdAndUpdate(productId, {$inc: {"quantity": quantity}}, {new: true}).exec()

export default {
  create,
  getById,
  update,
  remove,
  removeByShop,
  listByShop,
  listLatest,
  listRelated,
  listCategories,
  search,
  decreaseStock,
  increaseStock
}

// Handles auction room membership and bid events over Socket.io.
import auctionService from '../services/auction.service'

export default (server) => {
  const io = require('socket.io').listen(server)
  io.on('connection', function(socket){
    socket.on('join auction room', data => {
      socket.join(data.room)
    })
    socket.on('leave auction room', data => {
      socket.leave(data.room)
    })
    socket.on('new bid', data => {
      bid(data.bidInfo, data.room, socket)
    })
  })
  const bid = async (bid, auction, socket) => {
    try {
      let result = await auctionService.placeBid(auction, bid)
      if (result === null) {
        return socket.emit('bid rejected', {
          room: auction,
          reason: 'Bid must be higher than the current highest bid'
        })
      }
      io
        .to(auction)
        .emit('new bid', result)
    } catch(err) {
      console.log(err)
    }
  }
  return io
}
